#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct {
    unsigned char *digits;
    size_t length;
    size_t capacity;
} BigInt;

static int reserve_digits(BigInt *number, size_t needed)
{
    if (needed <= number->capacity) {
        return 1;
    }

    size_t capacity = number->capacity ? number->capacity : 1;
    while (capacity < needed) {
        if (capacity > (size_t)-1 / 2) {
            capacity = needed;
            break;
        }
        capacity *= 2;
    }

    unsigned char *digits = realloc(number->digits, capacity);
    if (!digits) {
        return 0;
    }
    number->digits = digits;
    number->capacity = capacity;
    return 1;
}

static int add_bigints(const BigInt *left, const BigInt *right, BigInt *sum)
{
    size_t length = left->length > right->length ? left->length : right->length;
    if (length == (size_t)-1 || !reserve_digits(sum, length + 1)) {
        return 0;
    }

    unsigned carry = 0;
    for (size_t i = 0; i < length; ++i) {
        unsigned digit = carry;
        if (i < left->length) {
            digit += left->digits[i];
        }
        if (i < right->length) {
            digit += right->digits[i];
        }
        sum->digits[i] = (unsigned char)(digit % 10);
        carry = digit / 10;
    }

    sum->length = length;
    if (carry) {
        sum->digits[sum->length++] = (unsigned char)carry;
    }
    return 1;
}

static void free_bigint(BigInt *number)
{
    free(number->digits);
    number->digits = NULL;
    number->length = 0;
    number->capacity = 0;
}

int main(int argc, char **argv)
{
    if (argc != 2 || argv[1][0] == '-' || argv[1][0] == '\0') {
        return 2;
    }

    char *end;
    errno = 0;
    unsigned long long n = strtoull(argv[1], &end, 10);
    if (errno == ERANGE || *end != '\0') {
        return 2;
    }

    BigInt a = {NULL, 0, 0};
    BigInt b = {NULL, 0, 0};
    BigInt c = {NULL, 0, 0};
    if (!reserve_digits(&a, 1) || !reserve_digits(&b, 1)) {
        free_bigint(&a);
        free_bigint(&b);
        return 1;
    }
    a.digits[0] = 0;
    a.length = 1;
    b.digits[0] = 1;
    b.length = 1;

    for (unsigned long long i = 0; i < n; ++i) {
        if (!add_bigints(&a, &b, &c)) {
            free_bigint(&a);
            free_bigint(&b);
            free_bigint(&c);
            return 1;
        }
        BigInt next = a;
        a = b;
        b = c;
        c = next;
    }

    for (size_t i = a.length; i > 0; --i) {
        putchar('0' + a.digits[i - 1]);
    }
    putchar('\n');

    free_bigint(&a);
    free_bigint(&b);
    free_bigint(&c);
    return 0;
}
